G=load()
def transform(grid):
    g=[row[:] for row in grid]; h,w=len(g),len(g[0])
    bg=max(set(x for r in g for x in r), key=[x for r in g for x in r].count)
    seen=set(); q=deque()
    for r in range(h):
        for c in (0,w-1):
            if g[r][c]==bg and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if g[r][c]==bg and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and g[nr][nc]==bg and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    # enclosed components
    allbg={(r,c) for r in range(h) for c in range(w) if g[r][c]==bg}
    enc=allbg-seen; vis=set()
    for cell in enc:
        if cell in vis: continue
        comp=set(); q=deque([cell]); vis.add(cell)
        while q:
            r,c=q.popleft(); comp.add((r,c))
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                n=(r+dr,c+dc)
                if n in enc and n not in vis: vis.add(n); q.append(n)
        if comp:
            rs=[r for r,c in comp]; cs=[c for r,c in comp]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            if len(comp)==(r1-r0+1)*(c1-c0+1):
                for r,c in comp: g[r][c]=4
    return g
